START TRANSACTION;

CREATE TABLE IF NOT EXISTS tassonomia_aree (
    id INT PRIMARY KEY,
    codice VARCHAR(20) UNIQUE NOT NULL,
    nome VARCHAR(100) NOT NULL,
    descrizione TEXT,
    ordine SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_macro_aree (
    id INT PRIMARY KEY,
    codice VARCHAR(20) UNIQUE NOT NULL,
    nome VARCHAR(150) NOT NULL,
    area_id INT NOT NULL,
    codice_cassazione VARCHAR(10),
    codice_stop_cnr VARCHAR(10),
    descrizione TEXT,
    ordine SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_tassonomia_macro_aree_area FOREIGN KEY (area_id) REFERENCES tassonomia_aree(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_sottobranches (
    id INT PRIMARY KEY,
    codice VARCHAR(20) UNIQUE NOT NULL,
    nome VARCHAR(200) NOT NULL,
    macro_area_id INT NOT NULL,
    descrizione TEXT,
    parole_chiave LONGTEXT,
    ordine SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_tassonomia_sottobranches_macro FOREIGN KEY (macro_area_id) REFERENCES tassonomia_macro_aree(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_procedimenti (
    id INT PRIMARY KEY,
    codice VARCHAR(20) UNIQUE NOT NULL,
    nome VARCHAR(200) NOT NULL,
    riferimento_normativo TEXT,
    area_id INT NULL,
    macro_area_id INT NULL,
    descrizione TEXT,
    termini_processuali LONGTEXT,
    documenti_richiesti LONGTEXT,
    ordine SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_tassonomia_procedimenti_area FOREIGN KEY (area_id) REFERENCES tassonomia_aree(id) ON DELETE SET NULL,
    CONSTRAINT fk_tassonomia_procedimenti_macro FOREIGN KEY (macro_area_id) REFERENCES tassonomia_macro_aree(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_varianti (
    id INT PRIMARY KEY,
    codice VARCHAR(20) UNIQUE NOT NULL,
    nome VARCHAR(150) NOT NULL,
    tipologia ENUM('rito', 'modalita', 'grado', 'soggetti', 'stato', 'economica', 'urgente'),
    descrizione TEXT,
    compatibilita LONGTEXT,
    ordine SMALLINT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_procedimento_varianti (
    procedimento_id INT NOT NULL,
    variante_id INT NOT NULL,
    PRIMARY KEY (procedimento_id, variante_id),
    CONSTRAINT fk_tassonomia_procedimento_varianti_proc FOREIGN KEY (procedimento_id) REFERENCES tassonomia_procedimenti(id) ON DELETE CASCADE,
    CONSTRAINT fk_tassonomia_procedimento_varianti_var FOREIGN KEY (variante_id) REFERENCES tassonomia_varianti(id) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS tassonomia_pratiche (
    id CHAR(36) PRIMARY KEY,
    numero_pratica VARCHAR(50) UNIQUE NOT NULL,
    cliente_id CHAR(36),
    area_id INT NULL,
    macro_area_id INT NULL,
    sottobranca_id INT NULL,
    procedimento_id INT NULL,
    stato ENUM('bozza', 'pendente', 'in_istruttoria', 'in_decisione', 'definita', 'archiviata', 'estinta') DEFAULT 'bozza',
    priorita ENUM('bassa', 'media', 'alta', 'urgente', 'critica') DEFAULT 'media',
    scadenza DATE,
    giudice VARCHAR(100),
    ruolo_cliente ENUM('attore', 'convenuto', 'terzo', 'assistito', 'mandante', 'parte_civile'),
    pct_fascicolo_id VARCHAR(100),
    note TEXT,
    tag_keywords LONGTEXT,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
    CONSTRAINT fk_tassonomia_pratiche_area FOREIGN KEY (area_id) REFERENCES tassonomia_aree(id) ON DELETE SET NULL,
    CONSTRAINT fk_tassonomia_pratiche_macro FOREIGN KEY (macro_area_id) REFERENCES tassonomia_macro_aree(id) ON DELETE SET NULL,
    CONSTRAINT fk_tassonomia_pratiche_sotto FOREIGN KEY (sottobranca_id) REFERENCES tassonomia_sottobranches(id) ON DELETE SET NULL,
    CONSTRAINT fk_tassonomia_pratiche_proc FOREIGN KEY (procedimento_id) REFERENCES tassonomia_procedimenti(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE INDEX idx_tassonomia_macro_aree_area ON tassonomia_macro_aree(area_id);
CREATE INDEX idx_tassonomia_sottobranches_macro ON tassonomia_sottobranches(macro_area_id);
CREATE INDEX idx_tassonomia_procedimenti_area ON tassonomia_procedimenti(area_id);
CREATE INDEX idx_tassonomia_procedimenti_macro ON tassonomia_procedimenti(macro_area_id);
CREATE INDEX idx_tassonomia_pratiche_taxonomy
ON tassonomia_pratiche(area_id, macro_area_id, sottobranca_id, procedimento_id);
CREATE INDEX idx_tassonomia_pratiche_stato_scadenza
ON tassonomia_pratiche(stato, scadenza);
CREATE FULLTEXT INDEX idx_tassonomia_pratiche_search
ON tassonomia_pratiche(note, tag_keywords);

-- 5.1 AREE (7)

-- 5.2 MACRO_AREE (16)

-- 5.3 SOTTOBRANCHES (83)

-- 5.4 PROCEDIMENTI (70)

-- 5.5 VARIANTI (63)

-- 5.6 MAPPING PROCEDIMENTO <-> VARIANTE (350+)

-- 5.7 PRATICHE DI ESEMPIO (20)

CREATE OR REPLACE VIEW vista_tassonomia_pratiche_complete AS
SELECT
    pr.numero_pratica,
    pr.stato,
    pr.priorita,
    pr.scadenza,
    a.nome AS area,
    m.nome AS macro_area,
    s.nome AS sottobranca,
    p.nome AS procedimento,
    GROUP_CONCAT(v.nome ORDER BY v.nome SEPARATOR ', ') AS varianti,
    pr.giudice,
    pr.ruolo_cliente,
    pr.note
FROM tassonomia_pratiche pr
JOIN tassonomia_aree a ON pr.area_id = a.id
JOIN tassonomia_macro_aree m ON pr.macro_area_id = m.id
JOIN tassonomia_sottobranches s ON pr.sottobranca_id = s.id
JOIN tassonomia_procedimenti p ON pr.procedimento_id = p.id
LEFT JOIN tassonomia_procedimento_varianti pv ON p.id = pv.procedimento_id
LEFT JOIN tassonomia_varianti v ON pv.variante_id = v.id
GROUP BY pr.id, pr.numero_pratica, pr.stato, pr.priorita, pr.scadenza, a.nome, m.nome, s.nome, p.nome, pr.giudice, pr.ruolo_cliente, pr.note;

SELECT
  (SELECT count(*) FROM tassonomia_aree) AS aree,
  (SELECT count(*) FROM tassonomia_macro_aree) AS macro_aree,
  (SELECT count(*) FROM tassonomia_sottobranches) AS sottobranches,
  (SELECT count(*) FROM tassonomia_procedimenti) AS procedimenti,
  (SELECT count(*) FROM tassonomia_varianti) AS varianti,
  (SELECT count(*) FROM tassonomia_procedimento_varianti) AS mapping,
  (SELECT count(*) FROM tassonomia_pratiche) AS pratiche;

SELECT 'aree' AS tabella, count(*) AS orfani FROM tassonomia_aree a
WHERE NOT EXISTS (SELECT 1 FROM tassonomia_macro_aree m WHERE m.area_id = a.id)
UNION ALL
SELECT 'macro_aree', count(*) FROM tassonomia_macro_aree m
WHERE NOT EXISTS (SELECT 1 FROM tassonomia_sottobranches s WHERE s.macro_area_id = m.id)
UNION ALL
SELECT 'procedimenti', count(*) FROM tassonomia_procedimenti p
WHERE NOT EXISTS (SELECT 1 FROM tassonomia_procedimento_varianti pv WHERE pv.procedimento_id = p.id);

COMMIT;
