(UUID(), 'PRAT-2026-LOC-01', 1, 101, 1001, 2006, 'pendente', 'alta', '2026-04-10', 'GdP Milano', 'attore', 'PCT-2026-MI-12345', 'Sfratto per morosità 6 mesi. Inquilino irreperibile. Richiesta convalida e decreto rilascio.', '{sfratto,morosità,locatore,urgente,decreto}'),
(UUID(), 'PRAT-2026-FAM-02', 1, 103, 1011, 2005, 'in_istruttoria', 'media', '2026-05-15', 'Trib. Roma Sez. Fam.', 'assistito', 'PCT-2026-RM-67890', 'Separazione consensuale. 2 figli minori. Assegno €800/mese. Casa assegnata alla madre. Piano genitoriale allegato.', '{separazione,consensuale,figli_minori,assegno,casa_familiare}'),
(UUID(), 'PRAT-2026-ESE-03', 4, 107, 1023, 2009, 'in_decisione', 'alta', '2026-03-25', 'Trib. Torino Esec.', 'attore', 'PCT-2026-TO-54321', 'Pignoramento c/c Intesa Sanpaolo. Credito €18.500 + interessi. Banca non ha risposto entro 10 gg. Istanza assegnazione.', '{pignoramento,presso_terzi,conto_corrente,assegnazione,credito}'),
(UUID(), 'PRAT-2026-VG-04', 5, 112, 1035, 2015, 'bozza', 'media', NULL, 'Trib. Firenze VG', 'mandante', NULL, 'Ricorso amministrazione di sostegno. Madre 82 anni, demenza vascolare iniziale. Figlio unico come beneficiario. CTU richiesta.', '{amministrazione_sostegno,demenza,incapacità,ricorso,CTU}'),
(UUID(), 'PRAT-2026-DIG-05', 7, 113, 1038, 2022, 'pendente', 'critica', '2026-02-28', 'Garante Privacy', 'assistito', NULL, 'Data breach e-commerce. 15.000 record esposti. Notifica entro 72h scaduta. Reclamo Garante + azione risarcitoria collettiva.', '{gdpr,data_breach,notifica_ritardata,risarcimento,collettivo}'),
(UUID(), 'PRAT-2026-LAV-06', 1, 102, 1007, 2004, 'in_istruttoria', 'alta', '2026-06-10', 'Trib. Napoli Lavoro', 'attore', 'PCT-2026-NA-11223', 'Licenziamento discriminatorio per malattia. Ricorso art. 414. Richiesta reintegro + risarcimento danno biologico. CTU INPS in corso.', '{licenziamento,discriminazione,malattia,ricorso_414,reintegro}'),
(UUID(), 'PRAT-2026-CRI-07', 4, 108, 1027, 2018, 'pendente', 'critica', '2026-04-05', 'Trib. Milano Fall.', 'mandante', 'PCT-2026-MI-FALL-001', 'Istanza composizione negoziata. Srl edilizia, debiti €450k. Esperto nominato. Misure protettive attive. Piano ristrutturazione in bozza.', '{crisi_impresa,composizione_negoziata,misure_protettive,esperto,piano}'),
